"""Independent black-box tests plus module-boundary checks for a fixed engineering fixture."""
from __future__ import annotations

import ast
import json
import os
import re
import subprocess
import sys
from pathlib import Path


def row(id, units=1, deps=(), component="api"):
    return {"id": id, "component": component, "units": units, "depends_on": list(deps)}


def request(changes=(), *, budget=5, environment="staging", action="plan", **extras):
    return {"environment": environment, "action": action, "budget": budget,
            "changes": list(changes), **extras}


def ok(actions=(), units=0):
    return {"status": "ok", "actions": list(actions), "units": units}


def error(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


BASE = {
    "stable-sort": (request([row("worker"), row("api", 2)], budget=3), ok(["api", "worker"], 3)),
    "empty-plan": (request(), ok()),
    "budget-denied": (request([row("api", 2), row("worker", 2)], budget=3), error("budget-exceeded")),
    "invalid-transport": ("{", error("invalid-json")),
    "invalid-request": ([], error("invalid-request")),
    "invalid-environment": (request(environment="preview"), error("invalid-environment")),
    "invalid-budget": (request(budget=True), error("invalid-budget")),
    "invalid-change": (request([row("api", False)]), error("invalid-change")),
}
STABLE_G1 = {
    "dependency-order": (request([row("api", 2, ["schema"]), row("schema")]),
                         ok(["schema", "api"], 3)),
    "replay-before-budget": (request([row("api", 2, ["schema"]), row("schema", 3), row("api", 2, ["schema"])],
                                     budget=2, applied=["schema"]), ok(["api"], 2)),
    "replay-identity-conflict": (request([row("api", 2), row("api", 3)]), error("conflicting-change")),
    "unknown-dependency": (request([row("api", 1, ["missing"])]), error("unknown-dependency")),
    "unknown-applied": (request([row("api")], applied=["missing"]), error("unknown-dependency")),
    "cycle": (request([row("api", 1, ["worker"]), row("worker", 1, ["api"])]), error("dependency-cycle")),
    "rollback-order": (request([row("api", 2, ["schema"]), row("schema"), row("worker")], action="rollback",
                               applied=["schema", "api", "worker"], budget=0), ok(["worker", "api", "schema"], 4)),
    "rollback-only-applied": (request([row("api", 2, ["schema"]), row("schema")], action="rollback",
                                      applied=["schema"], budget=0), ok(["schema"], 1)),
}
G1_ONLY = {
    "production-authorized": (request([row("worker")], environment="production"), ok(["worker"], 1)),
    "staging-quota-before-revision": (request([row("api", 4)], budget=4), ok(["api"], 4)),
}
G2_ONLY = {
    "production-frozen-plan": (request([row("worker")], environment="production"), error("production-frozen")),
    "production-frozen-before-graph": (request([row("api", 1, ["missing"])], environment="production",
                                               action="rollback"), error("production-frozen")),
    "staging-quota-current": (request([row("api", 4)], budget=9), error("budget-exceeded")),
    "retention-transitive": (request([row("api", 2, ["schema"]), row("schema", 1, ["platform"]),
                                    row("platform", 1), row("worker", 2, ["schema"])],
                                    action="rollback", applied=["schema", "api", "platform", "worker"], retain=["api"]),
                             ok(["worker"], 2)),
    "retention-validation": (request([row("api"), row("worker")], action="rollback",
                                      applied=["worker"], retain=["api"]), error("invalid-retain")),
}

MODULES = {"release", "policy", "journal", "planner"}
EDGES = {"release": {"planner"}, "policy": set(), "journal": set(), "planner": {"policy", "journal"}}
PATHS = [name + ".py" for name in sorted(MODULES)]


def case_table(stage):
    if stage == "base":
        return BASE
    if stage == "carry":
        return BASE | STABLE_G1
    if stage == "g1":
        return BASE | STABLE_G1 | G1_ONLY
    if stage == "g2":
        return BASE | STABLE_G1 | G2_ONLY
    raise ValueError("unknown benchmark stage")


def execute(source, incoming):
    content = incoming if isinstance(incoming, str) else json.dumps(incoming)
    args = ["/usr/bin/bwrap", "--unshare-all", "--unshare-user", "--disable-userns",
            "--die-with-parent", "--new-session", "--cap-drop", "ALL", "--clearenv",
            "--ro-bind", str(source), "/submission", "--ro-bind", "/usr", "/usr",
            "--symlink", "/usr/lib", "/lib", "--symlink", "/usr/lib64", "/lib64",
            "--proc", "/proc", "--dev", "/dev", "--size", "4194304", "--tmpfs", "/tmp",
            "--chdir", "/submission", "--setenv", "LC_ALL", "C.UTF-8", "--",
            "/usr/bin/python3", "-E", "-s", "-B", "/submission/release.py"]
    p = subprocess.run(args, input=content, text=True, encoding="utf-8", errors="replace",
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=3, check=False)
    if p.returncode != 0:
        exc = re.findall(r"^(?:[A-Za-z][A-Za-z0-9_.]*Error|[A-Za-z][A-Za-z0-9_.]*Exception): .{0,240}$", p.stderr, re.M)
        return None, p.returncode, exc[-1] if exc else "Process exited unsuccessfully"
    try:
        return json.loads(p.stdout), 0, None
    except ValueError:
        return None, 0, "The program must emit one JSON object."


def assess(source, cases):
    rows = []
    for id, (incoming, expected) in cases.items():
        try:
            actual, exit_code, exception = execute(source, incoming)
        except subprocess.TimeoutExpired:
            rows.append({"id": id, "status": "error", "failure": "case timeout"})
            continue
        except OSError as exc:
            rows.append({"id": id, "status": "error", "failure": type(exc).__name__})
            continue
        if actual == expected and type(actual) is dict and type(actual.get("units")) is int:
            rows.append({"id": id, "status": "passed"})
        else:
            # Report contract differences, keeping the test request and expected values outside the candidate.
            diff = [field for field in expected if type(actual) is not dict or expected[field] != actual.get(field)]
            rows.append({"id": id, "status": "failed", "exitCode": exit_code,
                         "failure": exception or "Result differs for fields: " + ", ".join(diff or ["object shape"])})
    return rows


def architecture(source):
    per_file = {}
    io_modules = {"os", "pathlib", "shutil", "subprocess", "socket", "urllib", "http", "sqlite3", "requests"}
    for name in sorted(MODULES):
        path = source / (name + ".py")
        if not path.is_file():
            per_file[name] = {"parse": False, "failure": "missing module"}
            continue
        try:
            tree = ast.parse(path.read_bytes(), filename=path.name)
        except SyntaxError:
            per_file[name] = {"parse": False, "failure": "syntax error"}
            continue
        imported, ops, functions = set(), set(), set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                imported.update(a.name.split(".")[0] for a in node.names)
            elif isinstance(node, ast.ImportFrom):
                imported.add((node.module or "").split(".")[0])
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                functions.add(node.name)
            elif isinstance(node, ast.Call):
                call = node.func
                if isinstance(call, ast.Name) and call.id in {"open", "print", "input", "exec", "eval", "__import__"}:
                    ops.add(call.id)
                if isinstance(call, ast.Attribute) and call.attr in {"read_bytes", "write_bytes", "read_text", "write_text",
                                                                     "unlink", "connect", "mkdir", "rmtree", "run"}:
                    ops.add(call.attr)
        per_file[name] = {"parse": True, "moduleImports": sorted(imported & MODULES),
                          "boundaryOk": imported & MODULES == EDGES[name],
                          "transportOnlyIO": not ops and not imported & io_modules if name != "release" else
                          not imported & io_modules and ops <= {"print", "input"},
                          "functions": sorted(functions), "lineCount": len(path.read_bytes().splitlines())}
    return per_file


if __name__ == "__main__":
    if sys.argv[1] == "--cases":
        print(json.dumps({stage: list(case_table(stage)) for stage in ("base", "carry", "g1", "g2")}))
        raise SystemExit
    source = Path(sys.argv[1]).resolve(strict=True)
    stage = sys.argv[2]
    rows = assess(source, case_table(stage))
    print(json.dumps({"stage": stage, "cases": rows, "architecture": architecture(source)}, ensure_ascii=True))

