"""Check that held-out cases distinguish valid implementations and seeded bugs."""
from __future__ import annotations

import argparse
import ast
import json
from pathlib import Path
import shutil
import tempfile

from base_assess import PATHS, assess, case_table
from hard_assess import hard_cases


REFERENCE = '''
def batch_failure(code, index=None):
    return {"status": "error", "error": code, "requestIndex": index, "results": [], "units": 0}


def batch_plan(body):
    allowed = {"action", "requests", "limit"} if USE_LIMIT else {"action", "requests"}
    if set(body) != allowed or not isinstance(body["requests"], list) or not 1 <= len(body["requests"]) <= 128:
        return batch_failure("invalid-batch")
    if USE_LIMIT and (type(body["limit"]) is not int or body["limit"] < 0):
        return batch_failure("invalid-batch")
    allowed_item = {"environment", "budget", "changes", "applied", "retain"}
    if USE_LIMIT:
        allowed_item.add("operation_id")
    results, seen, total = [], {}, 0
    for index, item in enumerate(body["requests"]):
        if not isinstance(item, dict) or item.keys() - allowed_item:
            return batch_failure("invalid-batch-item", index)
        if USE_LIMIT:
            operation_id = item.get("operation_id")
            if not isinstance(operation_id, str) or not 1 <= len(operation_id) <= 64:
                return batch_failure("invalid-batch-item", index)
            fingerprint = json.dumps(item, sort_keys=True)
            if operation_id in seen:
                if fingerprint != seen[operation_id]:
                    return batch_failure("conflicting-operation", index)
                continue
            seen[operation_id] = fingerprint
        current = single_plan({**item, "action": "rollback"})
        if current["status"] == "error":
            return batch_failure(current["error"], index)
        entry = {"actions": current["actions"], "units": current["units"]}
        if USE_LIMIT:
            entry["operationId"] = operation_id
        results.append(entry)
        total += current["units"]
    if USE_LIMIT and total > body["limit"]:
        return batch_failure("batch-limit-exceeded")
    return {"status": "ok", "results": results, "units": total}


def plan(body):
    if isinstance(body, dict) and body.get("action") == "rollback-many":
        return batch_plan(body)
    return single_plan(body)
'''


def write_candidate(source, destination, stage, mutation=None):
    for name in PATHS:
        shutil.copyfile(source / name, destination / name)
    target = destination / "planner.py"
    original = target.read_text(encoding="utf-8")
    tree = ast.parse(original)
    if not any(isinstance(node, ast.FunctionDef) and node.name == "retained_closure" for node in tree.body):
        raise ValueError("Use the G2 smoke baseline with retained_closure")
    original = original.replace("def plan(request):", "def single_plan(request):", 1)
    if mutation != "stop-at-unapplied":
        original = original.replace("if target in applied and target not in keep:", "if target not in keep:", 1)
    reference = "USE_LIMIT = " + repr(stage == "g4") + "\n" + REFERENCE
    if mutation == "emit-partial":
        reference = reference.replace('return batch_failure(current["error"], index)',
            'return {"status":"error","error":current["error"],"requestIndex":index,"results":results,"units":total}', 1)
    if mutation == "double-charge-retry":
        reference = reference.replace("                continue\n", "", 1)
    target.write_text("import json\n" + original + "\n" + reference, encoding="utf-8")


def main():
    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument("baseline", type=Path)
    cli.add_argument("--scratch", type=Path, required=True)
    args = cli.parse_args()
    baseline, scratch = args.baseline.resolve(strict=True), args.scratch.resolve(strict=True)
    summary = {}
    for stage in ("g3", "g4"):
        suite = hard_cases(stage, seed=71_403)
        old = case_table("g2")
        results = {}
        for mutation in (None, "unchanged-g2", "stop-at-unapplied", "emit-partial", "double-charge-retry"):
            if mutation == "double-charge-retry" and stage == "g3":
                continue
            if mutation == "unchanged-g2":
                root = baseline
                legacy, new = assess(root, old), assess(root, suite)
            else:
                with tempfile.TemporaryDirectory(prefix="oracle-", dir=scratch) as temporary:
                    root = Path(temporary)
                    write_candidate(baseline, root, stage, mutation)
                    legacy, new = assess(root, old), assess(root, suite)
            failures = [row["id"] for row in new if row["status"] != "passed"]
            assert all(row["status"] == "passed" for row in legacy), (stage, mutation, legacy)
            assert bool(mutation) == bool(failures), (stage, mutation, failures)
            results[mutation or "positive-reference"] = {"legacyPassed": len(old), "legacyTotal": len(old),
                "hardPassed": len(suite) - len(failures), "hardTotal": len(suite), "hardFailureIds": failures}
        summary[stage] = results
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()

