/** Replay synthetic cumulative cache counters through the production session event and advance handlers. */
import assert from "node:assert/strict";
import path from "node:path";
import { pathToFileURL } from "node:url";

const repo = path.resolve(process.argv[2]);
const { fixture, host, policy } = await import(pathToFileURL(path.join(repo, "test", "helpers.mjs")));
const check = { id: "C1", status: "supported", file: "functional.csv", start: 2, end: 2, basis: "原始记录是 19/20。" };
const unsupported = { id: "C2", status: "unsupported", basis: "实际来源没有给出该数字。",
  finding: { kind: "missing-evidence", quote: "平均耗时下降 25%", fix: "按可读实际依据复算。" } };

async function replay(total, duplicateAfterInterruption) {
  let evidence;
  await fixture(async (root, write) => {
    const config = structuredClone(policy);
    config.units.K01.cacheReadRotationThreshold = total;
    write("BUILDING-LOOP.json", JSON.stringify(config));
    const h = host(root);
    const first = await h.flow("root", "advance");
    const executor = first.childId;
    await h.flow(executor, "prepare");
    const count = 64;
    const quantum = Math.floor(total / count);
    for (let index = 1; index < count; index++) {
      await h.usage(executor, index, 1, quantum);
      // Duplicated steps occur in journal replay and must not add usage.
      if (index % 8 === 0) await h.usage(executor, index, 1, quantum);
    }
    const below = (count - 1) * quantum;
    await h.usage(executor, count, 1, total - below - 1);
    await h.usage(executor, count, 2, undefined);
    const atMinusOne = (await h.flow("root", "status")).units[0];
    assert.equal(atMinusOne.executorUsage.cacheReadTokens, total - 1);
    assert.equal(atMinusOne.executor, executor);
    await h.usage(executor, count, 3, 1);
    assert.equal((await h.flow("root", "status")).units[0].executorUsage.cacheReadTokens, total);
    if (duplicateAfterInterruption) {
      await h.interrupt(executor, 200);
      const resumed = await h.flow("root", "advance");
      assert.equal(resumed.childId, executor);
      await h.usage(executor, count, 3, 1);
      assert.equal((await h.flow("root", "status")).units[0].executorUsage.cacheReadTokens, total);
    }
    await h.flow(executor, "submit");
    const reviewer = (await h.flow("root", "advance")).childId;
    await h.usage(reviewer, 1, 1, total * 2);
    await h.flow(reviewer, "prepare");
    await h.flow(reviewer, "review", { checks: [check, unsupported] });
    const supplement = await h.flow("root", "advance");
    assert.notEqual(supplement.childId, executor);
    assert.equal(supplement.rotation.cacheReadTokens, total);
    assert.equal((await h.flow("root", "status")).units[0].executorUsage.cacheReadTokens, 0);
    await assert.rejects(h.file(supplement.childId, "read", "functional.csv"), /白名单/u);
    evidence = { suppliedSyntheticCacheReadTokens: total, providerRequests: 0, creditedUniqueSteps: 65,
      duplicateStepsIgnored: 7 + Number(duplicateAfterInterruption), missingUsageIgnored: true,
      reviewerUsageIgnored: true, noRotationInsideActiveOrInterruptedPhase: true,
      rotationAtSupplementBoundary: true, newExecutorStartsAtZero: true, noWidenedSourceGrant: true };
  });
  return evidence;
}

const traces = [];
for (const counter of [100_000_000, 1_000_000_000, 5_000_000_000]) {
  traces.push(await replay(counter, counter === 5_000_000_000));
}
console.log(JSON.stringify({ scope: "production handlers, synthetic DSH events, zero provider calls", traces }, null, 2));

