/** Exercise the production renderer, planner, lock and commit against dense synthetic books. */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

const [repo, scratch] = process.argv.slice(2).map(value => path.resolve(value));
const moduleUrl = name => pathToFileURL(path.join(repo, "governance", name));
const { digest } = await import(moduleUrl("policy.mjs"));
const { ledgerAction, exportLedger } = await import(moduleUrl("ledger.mjs"));
const { goalSnapshot } = await import(moduleUrl("goals.mjs"));
const { commitWorkspaceState, withWorkspaceLock, STATE_LIMIT } = await import(moduleUrl("transactions.mjs"));
const root = fs.mkdtempSync(path.join(scratch, "ledger-density-"));
const home = path.join(root, "host");
const project = path.join(root, "project");
fs.mkdirSync(home);
fs.mkdirSync(project);
const owner = "benchmark-owner";
const goal = "overview.md";
const candidate = "candidate.md";
const receipt = "receipt.json";
const stateFile = "state.json";
const goalText = "# Current goal\nKeep active issues until checked.\n";
const candidateText = "# Candidate\nConcrete verification done.\n";
fs.writeFileSync(path.join(project, goal), goalText);
fs.writeFileSync(path.join(project, candidate), candidateText);

function representativeItems(count, closed) {
  return Object.fromEntries(Array.from({ length: count }, (_, index) => {
    const id = "item-" + index.toString().padStart(6, "0");
    const statement = "保留版本依据与接口条件，在后续代码维护时对照。";
    const item = { id, kind: "planned", status: closed ? "obsolete" : "pending",
      owner, title: "组件边界与异常处置 " + index,
      note: statement, updatedAt: "2026-11-01T00:00:00.000Z" };
    if (closed) item.disposition = { outcome: "obsolete", basis: statement, checkpoint: "K01",
      evidence: { file: goal, start: 2, end: 2, sha256: digest(goalText) } };
    return [id, item];
  }));
}

function baseFrame(items, projection) {
  const policy = { hash: "", ledgerContext: [], goalContext: [goal], coordinator: { read: [goal, receipt], write: ["LEDGER.md"] },
    ledgerDocument: projection ? "LEDGER.md" : undefined, units: { K01: { covers: [], candidate, plainLast: false, claims: [],
      calculations: {}, phases: {
      "first-review": { evidence: [], read: [candidate] }, "final-review": { evidence: [], read: [candidate] },
    } } } };
  const active = { phase: "ledger-review", receipt, owner, serial: 1, executor: "worker",
    ledgerSeen: { [goal]: { hash: digest(goalText), ranges: [[1, 3]] } },
    proof: { reviewerCoverage: { records: [] }, auditorCoverage: { records: [] } } };
  const frame = { role: "coordinator", root: project, file: stateFile, policy, agent: { id: owner },
    reads: [goal, receipt], state: { units: { K01: active }, ledger: { revision: 1, items }, markers: {} } };
  const proof = JSON.stringify({ decision: "accept", phase: "final-review", reviewer: "reviewer",
    candidateSha256: digest(candidateText), goal: goalSnapshot(frame), goalFit: { pass: true },
    coverage: { version: 1, pending: [], rejected: [] },
    independentAudit: { auditor: "auditor", coverage: { version: 1, pending: [], rejected: [] } } });
  active.receiptHash = digest(proof);
  active.ledgerSeen[receipt] = { hash: digest(proof), ranges: [[1, 1]] };
  fs.writeFileSync(path.join(project, receipt), proof);
  return frame;
}

function duration(work) {
  const started = performance.now();
  try {
    const result = work();
    return { ms: Number((performance.now() - started).toFixed(3)), result };
  } catch (error) {
    return { ms: Number((performance.now() - started).toFixed(3)), error: error.message };
  }
}

function renderCase(count) {
  const frame = baseFrame(representativeItems(count, true), true);
  return duration(() => {
    const answer = exportLedger(frame);
    return { itemCount: answer.itemCount, bytes: frame.ledgerWrites.find(row => row.file === "LEDGER.md").after.length };
  });
}

function reviewCase(count) {
  const frame = baseFrame(representativeItems(count, false), false);
  const active = frame.state.units.K01;
  frame.state.ledger.items["unit-K01"] = { id: "unit-K01", title: "K01", owner, unit: "K01", status: "running" };
  const read = ledgerAction(frame, { action: "read", unit: "K01" });
  const args = { action: "review", unit: "K01", decisions: read.items.map(item =>
    item.unit ? { id: item.id, outcome: "completed", basis: "独立验收已完成。", evidence: { file: receipt, start: 1, end: 1 } }
      : { id: item.id, outcome: "keep", basis: "仍需后续确认。" }) };
  const result = duration(() => ledgerAction(frame, args));
  if (!result.error) assert.equal(active.phase, "closed");
  return result;
}

function commitCase(bytes) {
  const state = Buffer.from('{"data":"' + "a".repeat(bytes - 11) + '"}');
  const old = fs.existsSync(path.join(home, stateFile)) ? fs.readFileSync(path.join(home, stateFile)) : null;
  assert.equal(state.length, bytes);
  const frame = { file: stateFile, root: project, policy: {}, old };
  const answer = duration(() => withWorkspaceLock(home, stateFile, () => {
    commitWorkspaceState(home, frame, state);
    return { persistedBytes: fs.statSync(path.join(home, stateFile)).size };
  }));
  if (answer.error && old) assert.deepEqual(fs.readFileSync(path.join(home, stateFile)), old);
  return answer;
}

try {
  const rendering = Object.fromEntries([100, 300, 600, 1200].map(count => [count, renderCase(count)]));
  const reviews = Object.fromEntries([100, 300, 600, 1200].map(count => [count, reviewCase(count)]));
  const state = Object.fromEntries([STATE_LIMIT / 4, STATE_LIMIT, STATE_LIMIT + 1].map(size => [size, commitCase(size)]));
  assert.equal(rendering[100].result?.itemCount, 100);
  assert.match(rendering[1200].error, /上限/u);
  assert.ok(Object.values(reviews).every(row => row.result?.phase === "closed"), JSON.stringify(reviews));
  assert.equal(state[STATE_LIMIT].result?.persistedBytes, STATE_LIMIT);
  assert.match(state[STATE_LIMIT + 1].error, /上限/u);
  process.stdout.write(JSON.stringify({ scope: "synthetic state and receipts via production ledger/transaction functions",
    cacheOrModelUsageMeasured: false, rendering, reviews, state }, null, 2) + "\n");
} finally {
  assert.equal(path.dirname(fs.realpathSync(root)), fs.realpathSync(scratch));
  assert.match(path.basename(root), /^ledger-density-/u);
  fs.rmSync(root, { recursive: true });
}

