const checklist = [
  '先规划再实现，在项目里留下可供下一次会话接手的架构说明。',
  '把模块职责、依赖方向、实施和回退顺序及验证方法写清楚。',
  '在实际负责重放计费、图排序和失败保护的关键代码旁，解释非显然的原因或边界。',
  '按现行需求运行测试，记录通过、失败及未完成事项，留在项目内供接手。',
  '目标变更时检查已有文件和测试，修正过期的规划与说明并保留适用的旧行为。',
].join(' ');
function document(stage, building) {
  const goal = stage === 'g1'
    ? '# Release project\n\n当前目标 G3，按 SPEC.md 完成批量回退。\n'
    : '# Release project\n\n当前目标 G4，按 CHANGE-G2.md 更新，SPEC.md 其余要求继续有效。\n';
  return building ? goal + '\n## 分块入口\n\n- [分块索引](INDEX.md)\n' : goal;
}

function draftNotes() {
  return '# 发布规划与维护\n\n## 模块职责\n\n待填写。\n\n## 实施顺序\n\n待填写。\n\n## 回退顺序\n\n待填写。\n\n## 关键验证\n\n待填写。\n\n## 静态导入\n\n待由宿主生成。\n';
}

function units(publicKey, cases, suiteDigest) {
