    const read = [...files, 'INDEX.md', planFile];
    const edit = { read, write: files };
    return { candidate: 'release.py', plainLast: false, continuation: 'fresh',
      architecture: { module: 'architecture', headings: ['模块职责', '实施顺序', '回退顺序', '关键验证'],
        importsHeading: '静态导入' },
      codeTask: { sources: files, diagnostics: { checkSet: 'engineering-' + stage, protocol: 2,
        recipes: ['engineering-json', 'engineering-python-syntax'], reviewRecipes: ['engineering-json', 'engineering-python-syntax'],
        syntaxRecipe: 'engineering-python-syntax' },
        tests: { file: '.candidate-' + id + '.json', publicKey,
          previousSuiteSha256: digest(suiteDigest + ':' + previous), suiteSha256: digest(suiteDigest + ':' + current),
          requiredCases: cases[current].filter(key => !cases[previous].includes(key)),
          regression: { baselineFile: '.baseline-' + id + '.json', previousCases: cases[previous] } } },
      phases: { intake: edit, supplement: edit,
        'first-review': { read, evidence: [], receipt: 'receipts/' + id + '-first.json' },
        'final-review': { read, evidence: [], receipt: 'receipts/' + id + '-final.json' } } };
  };
  return { K01: config('g1', 'base', 'g1'), K02: config('g2', 'carry', 'g2') };
}

function signed(body, key) {
  return { ...body, signature: sign(null, codeRegressionSigningBytes(body), key).toString('base64') };
}

function sealBaseline(root, unit, policy, result, key) {
  const spec = policy.units[unit].codeTask.tests;
  save(root, spec.regression.baselineFile, signed({ spec: 'building-loop-code-regression-baseline/1',
    unit, policySha256: policy.hash, suiteSha256: spec.previousSuiteSha256, artifacts: rows(snapshot(root)),
    runId: 'bench-' + unit + '-baseline', cases: trimCases(result) }, key));
}

function sideFacts(root) {
  const docs = {};
  let remaining = 256 * 1024;
  function visit(directory = '', depth = 0) {
    if (depth > 4 || Object.keys(docs).length >= 48 || remaining <= 0) return;
    const here = join(root, directory);
    for (const entry of readdirSync(here, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      if (entry.name.startsWith('.') || entry.isSymbolicLink() || /^(?:node_modules|__pycache__|receipts)$/u.test(entry.name)) continue;
      const path = directory ? directory + '/' + entry.name : entry.name;
      if (entry.isDirectory()) visit(path, depth + 1);
      else if (entry.isFile() && projectDocs.test(path)) {
        const bytes = readFileSync(join(root, path));
        if (bytes.length > 64 * 1024 || bytes.length > remaining || Object.keys(docs).length >= 48) continue;
        const text = bytes.toString('utf8');
        if (text.includes('\0')) continue;
        docs[path] = { sha256: digest(bytes), text };
        remaining -= bytes.length;
      }
    }
  }
  visit();
  return docs;
}

function copyState(root, facts) {
  for (const [path, { text }] of Object.entries(facts)) save(root, path, text);
}

function additionalPythonFiles(root, directory = '', output = []) {
  for (const entry of readdirSync(join(root, directory), { withFileTypes: true })) {
    if (entry.name === '.git' || entry.name === '__pycache__' || entry.isSymbolicLink()) continue;
    const name = directory ? directory + '/' + entry.name : entry.name;
    if (entry.isDirectory()) additionalPythonFiles(root, name, output);
    else if (entry.isFile() && name.endsWith('.py') && !files.includes(name)) output.push(name);
  }
  return output.sort();
}

export function apply(ctx, config) {
  const { run, home, fixtures, capMs, completionMs, modes, caseInventory, seedFile, suiteIdentity } = config;
  const memberships = new Map();
  const eventPath = join(run, 'events.jsonl');
  const progress = (event, value) => appendFileSync(join(run, 'progress.jsonl'), JSON.stringify({ time: Date.now(), event, ...value }) + '\n');
  const keys = generateKeyPairSync('ed25519');
  const publicKey = keys.publicKey.export({ format: 'der', type: 'spki' }).toString('base64');
  const assessPath = join(fixtures, 'assess.py');
  const suiteDigest = suiteIdentity;
  const manifest = {
    spec: 'building-loop/1', goalContext: goalFiles, ledgerContext: goalFiles, ledgerDocument: 'LEDGER.md',
    coordinator: { read: [...goalFiles, 'INDEX.md', planFile, 'LEDGER.md',
      ...['K01', 'K02'].flatMap(id => ['receipts/' + id + '-first.json', 'receipts/' + id + '-final.json'])],
      write: [planFile, 'LEDGER.md'] },
    hierarchy: { overview: { path: 'PROJECT-GOAL.md', heading: '分块入口' },
      index: { path: 'INDEX.md', heading: '模块正文' }, modules: { architecture: planFile } },
    units: units(publicKey, caseInventory, suiteDigest),
  };
  const authorityBytes = JSON.stringify(manifest);
  const policy = parseAuthority(Buffer.from(authorityBytes));
  const seed = snapshot(join(fixtures, 'seed'));

  function state(owner, id) {
    const directory = join(home, 'building-loop-state');
    if (!existsSync(directory)) return null;
    for (const file of readdirSync(directory).filter(name => /^[a-f0-9]{64}\.json$/u.test(name))) {
      const stored = JSON.parse(readFileSync(join(directory, file), 'utf8'));
      if (stored.units?.[id]?.owner === owner || stored.engineeringCoordinator?.session === owner &&
        stored.engineeringCoordinator?.unit === id) return stored;
    }
    return null;
  }

  function signLatest(group) {
    const { challenge, latest } = group;
    if (!challenge || !latest?.results || latest.hash !== group.liveHash ||
      challenge.unit !== group.unit || fingerprint(snapshot(group.root)) !== latest.hash) return;
    const key = digest(JSON.stringify([challenge.goalSha256, challenge.nonce, latest.hash]));
    if (group.signed.has(key)) return;
    const { file, previousCases, requiredCases, protectedCases, artifacts: previousArtifacts, ...binding } = challenge;
    const expected = [...previousCases, ...requiredCases].sort();
    if (JSON.stringify(expected) !== JSON.stringify(latest.results.cases.map(row => row.id).sort())) return;
    // The trusted runner owns its snapshot and can sign changed bytes without
    // waiting for the model to request the same unit nonce and goal again.
    const receipt = signed({ ...binding, artifacts: latest.artifacts, runId: 'bench-' + key.slice(0, 20),
      cases: trimCases(latest.results) }, keys.privateKey);
    save(group.root, file, receipt);
    group.signed.add(key);
    progress('signed', { mode: group.mode, stage: group.stage, hash: latest.hash, goalSha256: binding.goalSha256,
      elapsedMs: Date.now() - group.started, protected: protectedCases.length, required: requiredCases.length,
      jointPass: [...protectedCases, ...requiredCases].every(id =>
        latest.results.cases.find(row => row.id === id).status === 'passed') });
  }

  ctx.on('session/event', (session, event) => {
    const parent = session.header?.parentSession;
    const group = memberships.get(session.id) ?? memberships.get(parent);
    if (!group || group.stopped) return;
    memberships.set(session.id, group);
    group.lastActivityAt = Date.now();
    if (!['assistant/message', 'assistant/attempt', 'request/header', 'tool/result', 'turn/end'].includes(event.type)) return;
    const { data } = event;
    const unit = group.unit;
    const current = isBuilding(group.mode) ? state(group.id, unit)?.units?.[unit] : null;
    const role = session.id === group.id ? isBuilding(group.mode) ? 'coordinator' : 'standard'
      : session.id === current?.auditor ? 'auditor' : session.id === current?.reviewer ? 'reviewer' : 'executor';
    const elapsedMs = Date.now() - group.started;
    const row = { mode: group.mode, stage: group.stage, session: digest(session.id).slice(0, 12), role, seq: event.seq,
      type: event.type, elapsedMs, window: elapsedMs < capMs ? 'comparison' : elapsedMs < completionMs ? 'extension' : 'cleanup' };
    if (event.type === 'assistant/message') {
      row.usage = data.usage;
      row.provider = data.message?.source?.provider;
      row.model = data.message?.source?.model;
      row.calls = (data.message?.content ?? []).filter(part => part.type === 'tool-call').map(part => {
        let args = part.arguments;
        try { if (typeof args === 'string') args = JSON.parse(args); } catch { args = {}; }
        const dedicatedReview = part.name === 'building_loop_code_review';
        return { name: part.name,
          action: args?.action ?? (dedicatedReview ? role === 'auditor' ? 'audit' : 'review' : undefined),
          unit: /^K0[12]$/u.test(args?.unit) ? args.unit : undefined,
          ...(dedicatedReview && args?.action === 'record' ? {
            compactDecisions: Array.isArray(args.decisions) ? args.decisions.length : 0,
            legacyRows: ['files', 'constraints'].reduce((total, key) => total + (args[key]?.length ?? 0), 0) +
              (args.architecture?.sections?.length ?? 0),
          } : {}),
          path: typeof (args?.path ?? args?.file_path) === 'string' &&
            /^(?:[A-Za-z0-9_. -]+\/)*[A-Za-z0-9_. -]{1,120}$/u.test(args.path ?? args.file_path)
            ? (args.path ?? args.file_path) : undefined,
          ...(dedicatedReview && args?.action === 'probe' ? {
            assertion: ['syntax', 'runtime', 'architecture'].includes(args.assertion) ? args.assertion : undefined,
            exampleId: /^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$/u.test(args.exampleId ?? '') ? args.exampleId : undefined,
            file: files.includes(args.file) ? args.file : undefined,
          } : {}) };
      });
    } else if (event.type === 'assistant/attempt') row.error = data.stream?.error?.code ?? data.stream?.error?.name;
    else if (event.type === 'request/header') row.tools = data.header?.tools?.map(tool => tool.name);
    else if (event.type === 'turn/end') {
      row.reason = data.reason?.kind;
      if (session.id === group.id) group.rootEnded = row.reason;
    } else if (event.type === 'tool/result') {
      row.error = data.message?.isError;
      const resultText = data.message?.content?.find(item => item.type === 'text')?.text;
      if (row.error) row.detail = String(resultText ?? '').slice(0, 450);
      else {
        try {
          const result = JSON.parse(resultText);
          const challenge = result.codeTask?.regressionProof;
          if (challenge?.unit === unit) {
            group.challenge = challenge;
            signLatest(group);
          }
          if (result.phase) row.phase = result.phase;
          if (result.status === 'needs-review') {
            row.needsReview = { message: result.message?.slice(0, 600), next: result.next, progress: result.progress };
          }
          if (Array.isArray(result.architecture?.conflicts) && result.architecture.conflicts.length) {
            row.architectureConflicts = result.architecture.conflicts.slice(0, 32);
          }
          if (typeof result.checkpoint?.unit === 'string' && /^K0[12]$/u.test(result.checkpoint.unit)) {
            row.boundCheckpoint = { unit: result.checkpoint.unit, goalSha256: result.checkpoint.goalSha256 };
          }
          if (result.codeReview || result.readiness || result.codeSubmission) {
            row.observedContract = Object.keys(result).filter(key => /code|readiness/i.test(key));
          }
          const summarizeProbe = probe => /^probe-[a-f0-9]{36}$/u.test(probe?.id ?? '') &&
            ['match', 'mismatch', 'unavailable'].includes(probe.outcome) ? { id: probe.id, outcome: probe.outcome,
              assertion: ['syntax', 'runtime', 'architecture'].includes(probe.type) ? probe.type : undefined,
              exampleId: /^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$/u.test(probe.exampleId ?? '') ? probe.exampleId : undefined,
              recipe: ['engineering-json', 'engineering-python-syntax'].includes(probe.recipe) ? probe.recipe : undefined,
              snapshotSha256: /^[a-f0-9]{64}$/u.test(probe.snapshotSha256 ?? '') ? probe.snapshotSha256 : undefined,
              expectedExitCode: probe.expected?.exitCode, actualExitCode: probe.actual?.exitCode } : undefined;
          const proof = summarizeProbe(result);
          if (proof) row.probe = proof;
          if (Array.isArray(result.examples)) {
            row.exampleProbes = result.examples.slice(0, 8).map(summarizeProbe).filter(Boolean);
          }
        } catch {}
      }
    }
    appendFileSync(eventPath, JSON.stringify(row) + '\n');
  });

  function observe(group) {
    const current = snapshot(group.root);
    const hash = fingerprint(current);
    if (hash !== group.liveHash) {
      group.liveHash = hash;
      group.changed = Date.now();
      progress('source', { mode: group.mode, stage: group.stage, hash, elapsedMs: group.changed - group.started });
    }
    if (group.running || group.startedHashes.has(hash) || Date.now() - group.changed < 350) return;
    group.startedHashes.add(hash);
    const source = join(run, 'assess', group.mode, group.stage, hash.slice(0, 20));
    materialize(source, current);
    group.running = evaluate({ fixture: assessPath, temp: join(run, 'tmp'), source, stage: group.stage, seedFile })
      .then(results => {
        save(source, 'assessment.json', results);
        if (group.stopped || hash !== group.liveHash) return;
        group.latest = { hash, results, artifacts: rows(current) };
        signLatest(group);
        progress('assessed', { mode: group.mode, stage: group.stage, hash, elapsedMs: Date.now() - group.started,
          passed: results.cases.filter(caseRow => caseRow.status === 'passed').length, total: results.cases.length });
      })
      .catch(error => { group.problems.push({ phase: 'observer', name: error.name, code: error.code }); })
      .finally(() => { group.running = null; });
  }

  function stageAgents(group, active) {
    const ids = new Set([group.id, active?.actor, active?.executor, active?.reviewer, active?.auditor]);
    for (const [id, membership] of memberships) if (membership === group) ids.add(id);
    return Array.from(ids).filter(Boolean).map(id => ctx.agents.get(id)).filter(Boolean);
  }

  function idle(agent) {
    return agent.status === 'idle' && !agent.inbox?.nextTurn?.length;
  }

  function roleIdentities(active) {
    return active && Object.fromEntries(['executor', 'reviewer', 'auditor'].filter(role => active[role])
      .map(role => [role, digest(active[role]).slice(0, 12)]));
  }

  function capture(group, phase, active, stored, terminal, target) {
    const after = snapshot(group.root);
    const facts = sideFacts(group.root);
    const extraPython = additionalPythonFiles(group.root);
    materialize(target, after);
    copyState(target, facts);
    const registration = active?.engineeringArchitecture ?? stored?.engineeringArchitecture?.[planFile];
    return { after, facts, target, elapsedMs: Date.now() - group.started, terminal, nativePhase: phase ?? null,
      extraPython,
      roleIdentity: roleIdentities(active), acceptedProofSha256: active?.codeIntake?.qualification?.receiptSha256,
      registeredArchitecture: registration && { file: registration.file, sha256: registration.sha256,
        contentsSha256: registration.contentsSha256, goalSha256: registration.goalSha256 },
      ledgerItems: Object.values(stored?.ledger?.items ?? {}).map(({ id, kind, status, owner, originalOwner, handedOffFrom }) => ({
        id, kind, status, owner: owner && digest(owner).slice(0, 12), originalOwner: originalOwner && digest(originalOwner).slice(0, 12),
        handedOffFrom: handedOffFrom && digest(handedOffFrom).slice(0, 12) })) };
  }

  async function stopOnlyStage(group, active) {
    const attempted = [];
    const failed = [];
    const until = Date.now() + 6_000;
    while (Date.now() < until) {
      const running = stageAgents(group, active).filter(agent => !idle(agent));
      if (!running.length) return { attempted, failed, allIdle: true };
      for (const agent of running) {
        const id = digest(agent.id).slice(0, 12);
        if (attempted.includes(id)) continue;
        attempted.push(id);
        try { agent.cancel({ kind: 'user' }, { keepInbox: false }); }
        catch (error) { failed.push({ id, name: error.name }); }
      }
      await sleep(150);
    }
    return { attempted, failed, allIdle: stageAgents(group, active).every(idle) };
  }

  async function runStage(mode, preset, stage, root, origin) {
    const unit = stage === 'g1' ? 'K01' : 'K02';
    const baselineStage = stage === 'g1' ? 'base' : 'carry';
    const before = snapshot(root);
    const basePath = join(run, 'baseline', mode, stage);
    materialize(basePath, before);
    const baseline = await evaluate({ fixture: assessPath, temp: join(run, 'tmp'), source: basePath, stage: baselineStage, seedFile });
    save(basePath, 'assessment.json', baseline);
    if (isBuilding(mode)) sealBaseline(root, unit, policy, baseline, keys.privateKey);
    const { sessionId: id } = await ctx.sessionController.create({ cwd: root, agentPreset: preset });
    await ctx.sessionController.selectModel({ sessionId: id, ...model });
    const group = { id, mode, stage, unit, root, problems: [], signed: new Set(), startedHashes: new Set(), started: Date.now(),
      lastActivityAt: Date.now() };
    memberships.set(id, group);
    const ordinary = stage === 'g1' ? g1Message : g2Message;
    const prompt = mode === 'standard-checklist' ? ordinary + '\n\n' + checklist : ordinary;
    observe(group);
    const accepted = await ctx.sessionController.prompt({ sessionId: id, requestId: randomUUID(), clientTimeZone: 'Asia/Shanghai',
      content: [{ type: 'text', text: prompt }] }, AbortSignal.timeout(8_000));
    if (!accepted.accepted) throw Error('Native user prompt was not accepted for ' + mode + '/' + stage);
    let terminal, stored, active, phase, comparison;
    const frozenRoot = join(run, 'frozen', mode, stage);
    const checkpointRoot = join(run, 'checkpoint', mode, stage);
    while (Date.now() - group.started < completionMs) {
      stored = isBuilding(mode) ? state(id, unit) : null;
      active = stored?.units?.[unit]?.owner === id ? stored.units[unit] : undefined;
      if (active?.phase !== phase) {
        phase = active?.phase;
        progress('phase', { mode, stage, phase, elapsedMs: Date.now() - group.started });
      }
      const settled = Date.now() - group.lastActivityAt >= 600 && stageAgents(group, active).every(idle);
      terminal = !isBuilding(mode) ? group.rootEnded && settled ? group.rootEnded : undefined
        : finish.has(phase) && settled ? phase
        : phase === 'blocked' && group.rootEnded && settled ? 'blocked' : undefined;
      if (!comparison && Date.now() - group.started >= capMs) {
        comparison = capture(group, phase, active, stored, 'cap', checkpointRoot);
        progress('comparison-cap', { mode, stage, phase, elapsedMs: comparison.elapsedMs, hash: fingerprint(comparison.after) });
      }
      if (terminal) break;
      observe(group);
      await sleep(150);
    }
    const frozen = capture(group, phase, active, stored, terminal ?? 'completion-cap', frozenRoot);
    comparison ??= frozen;
    const cleanup = terminal ? { attempted: [], failed: [], allIdle: true } : await stopOnlyStage(group, active);
    group.stopped = true;
    const final = await evaluate({ fixture: assessPath, temp: join(run, 'tmp'), source: frozen.target, stage, seedFile });
    const scoredCheckpoint = comparison === frozen ? final
      : await evaluate({ fixture: assessPath, temp: join(run, 'tmp'), source: comparison.target, stage, seedFile });
    const result = { mode, stage, unit, capMs, completionMs, elapsedMs: frozen.elapsedMs, terminal: frozen.terminal,
      nativePhase: frozen.nativePhase, carry: origin, session: digest(id).slice(0, 12), roleIdentity: frozen.roleIdentity,
      prompt, targetFiles: goalFiles.map(path => ({ path, sha256: frozen.facts[path]?.sha256 })),
      before: rows(before), after: rows(frozen.after), baseline, final,
      documents: frozen.facts, notes: frozen.facts[planFile] ?? null, ledger: frozen.facts['LEDGER.md'] ?? null, ledgerItems: frozen.ledgerItems, extraPython: frozen.extraPython,
      registeredArchitecture: frozen.registeredArchitecture,
      acceptedProofSha256: frozen.acceptedProofSha256, problems: group.problems, cleanup,
      comparison: { elapsedMs: comparison.elapsedMs, terminal: comparison.terminal, nativePhase: comparison.nativePhase,
        after: rows(comparison.after), documents: comparison.facts, notes: comparison.facts[planFile] ?? null, ledgerItems: comparison.ledgerItems, extraPython: comparison.extraPython,
        acceptedProofSha256: comparison.acceptedProofSha256, registeredArchitecture: comparison.registeredArchitecture,
        assessment: scoredCheckpoint } };
    save(run, mode + '-' + stage + '.json', result);
    const handoffSafe = !isBuilding(mode) ? !!terminal : finish.has(terminal);
    return { result, after: frozen.after, afterFacts: frozen.facts, root, handoffSafe };
  }

  async function lane(mode, preset) {
    const short = isBuilding(mode) ? 'bl' : mode === 'standard-checklist' ? 'check' : 'std';
    const laneRoot = join(run, 'work', short);
    materialize(laneRoot, seed);
    save(laneRoot, 'PROJECT-GOAL.md', document('g1', isBuilding(mode)));
    save(laneRoot, 'SPEC.md', readFileSync(join(fixtures, 'SPEC.md'), 'utf8'));
    save(laneRoot, 'CHANGE-G2.md', '# 未发布目标\n\n当前未有后续修订。\n');
    if (isBuilding(mode)) {
      save(laneRoot, 'INDEX.md', '# 工程索引\n\n## 模块正文\n\n- [architecture](modules/architecture.md)\n');
      save(laneRoot, planFile, draftNotes());
      save(laneRoot, 'BUILDING-LOOP.json', authorityBytes);
    }
    const first = await runStage(mode, preset, 'g1', laneRoot, 'same-frozen-seed');
    // Only a completed or retired Building-loop unit is a durable takeover
    // boundary. Blocked work and timed-out work keep the original unchanged.
    const continuation = first.handoffSafe ? laneRoot : join(run, 'work', short + '2');
    if (continuation !== laneRoot) {
      materialize(continuation, first.after);
      copyState(continuation, first.afterFacts);
      if (isBuilding(mode)) save(continuation, 'BUILDING-LOOP.json', authorityBytes);
    }
    save(continuation, 'PROJECT-GOAL.md', document('g2', isBuilding(mode)));
    save(continuation, 'CHANGE-G2.md', readFileSync(join(fixtures, 'CHANGE-G2.md'), 'utf8'));
    progress('owner-change', { mode, from: 'g1', to: 'g2', sameWorkspace: continuation === laneRoot,
      previous: fingerprint(first.after), nextGoal: digest(document('g2', isBuilding(mode))), previousOwner: first.result.session,
      previousTerminal: first.result.terminal, previousLedgerSha256: first.afterFacts['LEDGER.md']?.sha256,
      newRequirementSha256: digest(readFileSync(join(continuation, 'CHANGE-G2.md'))) });
    const carry = continuation === laneRoot ? 'same-workspace-new-session' : first.result.terminal === 'blocked'
      ? 'frozen-workspace-continuation-after-block' : 'frozen-workspace-continuation-after-timeout';
    const second = await runStage(mode, preset, 'g2', continuation, carry);
    return { mode, stages: [first.result, second.result] };
  }

  let begun = false;
  const timer = setInterval(async () => {
    if (begun) return;
    begun = true;
    try {
      const presets = await ctx.agentPresets.list();
      const standard = presets.find(item => item.id === 'standard' || item.id === 'default');
      const bl = presets.find(item => item.id === 'building-loop');
      if (!standard || !bl) { begun = false; return; }
      clearInterval(timer);
      if (config.preflight) {
        const source = join(run, 'preflight-seed');
        materialize(source, seed);
        const result = await evaluate({ fixture: assessPath, temp: join(run, 'tmp'), source, stage: 'base', seedFile });
        if (result.cases.some(row => row.status !== 'passed')) throw Error('Frozen base fixture failed');
        save(run, 'result.json', { model, capMs, lanes: [], preflight: { presets: [standard.id, bl.id], baseline: result } });
        return;
      }
      const both = await Promise.allSettled(modes.map(async (mode, index) => {
        if (index) await sleep(350);
        return lane(mode, isBuilding(mode) ? bl.id : standard.id);
      }));
      save(run, 'result.json', { model, capMs, lanes: both.map(value => value.status === 'fulfilled'
        ? value.value : { error: String(value.reason) }) });
    } catch (error) {
      clearInterval(timer);
      save(run, 'result.json', { error: String(error), model, capMs });
    }
  }, 250);
  ctx.on('dispose', () => clearInterval(timer));
}

