const lines = bytes => bytes.toString('utf8').trim().split('\n').filter(Boolean).map(JSON.parse);

function journal(path) {
  const data = readFileSync(path), starts = [];
  for (let from = 0; (from = data.indexOf(magic, from)) >= 0; from += magic.length) starts.push(from);
  return starts.flatMap((from, index) => lines(zstdDecompressSync(data.subarray(from, starts[index + 1]))));
