    .map(event => [event.data?.message?.toolCallId, event.data?.message]));
  const length = value => typeof value === 'string' ? value.length : null;
  return events.flatMap(event => (event.data?.message?.content ?? []).flatMap(part => {
    const dedicated = part.name === 'building_loop_code_review';
    if (event.type !== 'assistant/message' || part.type !== 'tool-call' || (!dedicated && part.name !== 'building_loop')) return [];
    let args;
    try { args = typeof part.arguments === 'string' ? JSON.parse(part.arguments) : part.arguments; } catch { return []; }
    const action = dedicated && (!args?.action || ['submit', 'record'].includes(args.action))
      ? role === 'auditor' ? 'audit' : 'review'
      : args?.action;
    const review = dedicated ? args : args?.codeReview;
    if (!['review', 'audit'].includes(action) || !review) return [];
    const response = toolResults.get(part.id);
    const responseText = response?.content?.find(item => item.type === 'text')?.text;
    let resulting;
    try { if (response && !response.isError) resulting = JSON.parse(responseText); } catch {}
    return [{ seq: event.seq, tool: part.name, action, operation: args.action,
      hasChecks: args.checks !== undefined, hasQuality: args.quality !== undefined,
      files: Array.isArray(review.files) ? review.files.map(row => ({ file: row?.file, basisChars: length(row?.basis),
        comments: (Array.isArray(row?.comments) ? row.comments : [row?.comment]).filter(Boolean).map(note => ({ status: note.status,
          basisChars: length(note.basis), quoteChars: length(note.quote), start: note.start, end: note.end })) })) : [],
      constraints: Array.isArray(review.constraints) ? review.constraints.map(row => ({ caseId: row?.caseId, basisChars: length(row?.basis) })) : [],
      decisions: Array.isArray(review.decisions) ? review.decisions.map(row => ({ id: row?.id, status: row?.status,
        basisChars: length(row?.basis), refs: row?.refs })) : [],
      findings: Array.isArray(review.findings) ? review.findings.map(row => ({ id: row?.id, kind: row?.kind, file: row?.file,
        start: row?.start, end: row?.end, issueChars: length(row?.issue), fixChars: length(row?.fix),
        observation: typeof row?.observation === 'string' ? row.observation.slice(0, 420) : undefined,
        issue: typeof row?.issue === 'string' ? row.issue.slice(0, 420) : undefined,
        fix: typeof row?.fix === 'string' ? row.fix.slice(0, 420) : undefined,
        evidence: Array.isArray(row?.evidence) ? row.evidence.map(ref => ({ file: ref?.file, start: ref?.start,
          end: ref?.end, relation: ref?.relation })) : undefined })) : [],
      findingsDone: review.findingsDone, architectureStatus: review.architecture?.status,
      architectureSections: Array.isArray(review.architecture?.sections) ? review.architecture.sections.map(section => ({
        heading: section?.heading, status: section?.status, basisChars: length(section?.basis),
        source: section?.source, evidenceCount: Array.isArray(section?.evidence) ? section.evidence.length : undefined,
      })) : undefined,
      result: response ? { error: response.isError, status: resulting?.status, phase: resulting?.phase, progress: resulting?.progress,
        problems: resulting?.errors,
        detail: response.isError ? responseText?.slice(0, 450) : undefined } : null }];
  }));
}

function coordinatorCalls(events) {
  const toolResults = new Map(events.filter(event => event.type === 'tool/result')
    .map(event => [event.data?.message?.toolCallId, event.data?.message]));
  return events.flatMap(event => (event.data?.message?.content ?? []).flatMap(part => {
    if (event.type !== 'assistant/message' || part.type !== 'tool-call' || part.name !== 'building_loop') return [];
    let args;
    try { args = typeof part.arguments === 'string' ? JSON.parse(part.arguments) : part.arguments; } catch { return []; }
    const response = toolResults.get(part.id);
    let outcome;
    try { if (response && !response.isError) outcome = JSON.parse(response.content.find(item => item.type === 'text')?.text); } catch {}
    return [{ seq: event.seq, action: args?.action, unit: args?.unit, boundUnit: outcome?.checkpoint?.unit,
      boundGoalSha256: outcome?.checkpoint?.goalSha256, architectureSha256: outcome?.architecture?.sha256,
      error: response?.isError, detail: response?.isError ? response.content?.find(item => item.type === 'text')?.text?.slice(0, 450) : undefined }];
  }));
}

function architectureCalls(events) {
  const results = new Map(events.filter(event => event.type === 'tool/result')
    .map(event => [event.data?.message?.toolCallId, event]));
  return events.flatMap(event => (event.data?.message?.content ?? []).flatMap(part => {
    if (event.type !== 'assistant/message' || part.type !== 'tool-call' || part.name !== 'building_loop_file') return [];
    let args;
    try { args = typeof part.arguments === 'string' ? JSON.parse(part.arguments) : part.arguments; } catch { return []; }
    if (args?.path !== 'modules/architecture.md' || !['write', 'edit'].includes(args.action)) return [];
    const response = results.get(part.id);
    const message = response?.data?.message;
    let outcome;
    try { if (message && !message.isError) outcome = JSON.parse(message.content.find(item => item.type === 'text')?.text); } catch {}
    return [{ seq: event.seq, time: event.time, resultSeq: response?.seq, action: args.action, path: args.path,
      error: message?.isError, changed: outcome?.changed, sha256: outcome?.sha256 }];
  }));
}

for (const path of process.argv.slice(2)) {
  const run = resolve(path);
  linux(run);
  const eventFile = join(run, 'events.jsonl');
  if (!existsSync(eventFile)) continue;
  const observed = lines(readFileSync(eventFile));
  const roles = new Map(observed.map(({ session, mode, stage, role }) => [session, { mode, stage, role }]));
  for (const mode of ['standard', 'standard-checklist', 'building-loop']) for (const stage of ['g1', 'g2']) {
    const stageFile = join(run, mode + '-' + stage + '.json');
    if (!existsSync(stageFile)) continue;
    const record = JSON.parse(readFileSync(stageFile, 'utf8'));
    roles.set(record.session, { mode, stage, role: mode === 'building-loop' ? 'coordinator' : 'standard' });
    for (const [role, id] of Object.entries(record.roleIdentity ?? {})) roles.set(id, { mode, stage, role });
  }
  const postHostWorkflow = [];
  const stateRoot = join(run, 'h', 'building-loop-state');
  if (existsSync(stateRoot)) for (const file of readdirSync(stateRoot).filter(name => /^[a-f0-9]{64}\.json$/u.test(name))) {
    const state = JSON.parse(readFileSync(join(stateRoot, file), 'utf8'));
    for (const [unit, active] of Object.entries(state.units ?? {})) {
      if (typeof active.owner !== 'string') continue;
      const owner = hash(active.owner);
      const stage = roles.get(owner)?.stage;
      if (!stage) continue;
      const identities = Object.fromEntries(['executor', 'reviewer', 'auditor'].filter(role => typeof active[role] === 'string')
        .map(role => [role, hash(active[role])]));
      for (const [role, id] of Object.entries(identities)) roles.set(id, { mode: 'building-loop', stage, role });
      postHostWorkflow.push({ unit, stage, owner, phase: active.phase, roleIdentity: identities,
        receiptSha256: active.receiptHash, ledgerReviewRecorded: !!active.ledgerDecision,
        ledgerItems: Object.values(state.ledger?.items ?? {}).map(({ id, kind, status }) => ({ id, kind, status })) });
    }
  }
  const within = new Set(observed.filter(row => row.type === 'assistant/message').map(row => row.session + '|' + row.seq));
  const rows = [], unknown = [], errors = [], reviews = [], assistantFinals = [], coordinatorDecisions = [], architectureWrites = [];
  const home = join(run, 'h', 'sessions');
  if (existsSync(home)) for (const workspace of readdirSync(home, { withFileTypes: true })) {
    if (!workspace.isDirectory()) continue;
    for (const entry of readdirSync(join(home, workspace.name), { withFileTypes: true })) {
      if (!entry.isDirectory() || !/^(?:session-)?[0-9a-f-]{36}$/u.test(entry.name)) continue;
      const candidates = [hash(entry.name), hash(entry.name.replace(/^session-/u, ''))];
      const id = candidates.find(candidate => roles.has(candidate)) ?? candidates[0];
      const file = join(home, workspace.name, entry.name, 'session.v4.jsonl.zstd');
      if (!existsSync(file)) continue;
      try {
        const entries = journal(file);
        const parent = entries.find(event => event.type === 'session')?.parentSession;
        if (!roles.has(id) && typeof parent === 'string' && roles.has(hash(parent))) {
          roles.set(id, { ...roles.get(hash(parent)), role: 'late-child' });
        }
        if (roles.has(id)) for (const review of structuredReviews(entries, roles.get(id).role)) {
          reviews.push({ ...roles.get(id), session: id, withinWindow: within.has(id + '|' + review.seq), ...review });
        }
        if (roles.get(id)?.role === 'coordinator') for (const call of coordinatorCalls(entries)) {
          coordinatorDecisions.push({ ...roles.get(id), session: id, withinWindow: within.has(id + '|' + call.seq), ...call });
        }
        if (roles.has(id)) for (const call of architectureCalls(entries)) {
          architectureWrites.push({ ...roles.get(id), session: id, withinWindow: within.has(id + '|' + call.seq), ...call });
        }
        if (roles.has(id)) {
          const last = entries.filter(event => event.type === 'assistant/message' && within.has(id + '|' + event.seq))
            .map(event => ({ seq: event.seq, parts: event.data?.message?.content ?? [] }))
            .filter(({ parts }) => parts.some(part => part.type === 'text' && part.text?.trim())
              && !parts.some(part => part.type === 'tool-call')).at(-1);
          if (last) assistantFinals.push({ ...roles.get(id), session: id, seq: last.seq,
            text: last.parts.filter(part => part.type === 'text').map(part => part.text).join('\n').slice(0, 2400) });
        }
        for (const event of entries) {
          if (event.type !== 'assistant/message' || within.has(id + '|' + event.seq)) continue;
          const data = { session: id, seq: event.seq, usage: event.data?.usage,
            provider: event.data?.message?.source?.provider, model: event.data?.message?.source?.model };
          if (roles.has(id)) rows.push({ ...roles.get(id), ...data });
          else unknown.push(data);
        }
      } catch (error) { errors.push({ session: id, name: error.name }); }
    }
  }
  writeFileSync(join(run, 'persisted-usage-outside-window.json'), JSON.stringify({ run: basename(run), rows, unknown, errors, reviews, assistantFinals, coordinatorDecisions, postHostWorkflow, architectureWrites }, null, 2) + '\n');
}

