from __future__ import annotations

from collections import defaultdict
from pathlib import Path
import json
import sys

MODES = ("standard", "standard-checklist", "building-loop")
KEYS = ("inputTokens", "cacheReadTokens", "cacheWriteTokens", "outputTokens", "totalTokens")
WINDOWS = ("comparison", "extension", "cleanup", "persisted")

def empty():
    return dict.fromkeys(KEYS, 0) | {"known": 0, "missing": 0}

def add(dst, value, bucket=False):
    if value is None:
        dst["missing"] += 1
        return
    if bucket:
        dst["known"] += value["withUsage"]
        dst["missing"] += value["responses"] - value["withUsage"]
    else:
        dst["known"] += 1
    for name in KEYS:
        dst[name] += value.get(name, 0)

def cache(value):
    inputs = value["inputTokens"] + value["cacheReadTokens"] + value["cacheWriteTokens"]
    return (round(100 * value["cacheReadTokens"] / inputs, 4) if inputs else None)

def merged(rows):
    return {key: sum(item[key] for item in rows) for key in (*KEYS, "known", "missing")}

def analyze(doc):
    modes = {(mode, window): empty() for mode in MODES for window in WINDOWS}
    stages = []
    for run in doc["runs"]:
        scoped = defaultdict(empty)
        for window, role_usage in run["roleUsageByWindow"].items():
            for row in role_usage:
                key = (row["mode"], row["stage"], window)
                add(modes[(row["mode"], window)], row, True)
                add(scoped[key], row, True)
        late = run["persistedUsageOutsideWindow"]
        for row in late.get("rows", []):
            key = (row["mode"], row["stage"], "persisted")
            add(modes[(row["mode"], "persisted")], row.get("usage"))
            add(scoped[key], row.get("usage"))
        for stage in run["stages"]:
            mode, name = stage["mode"], stage["stage"]
            per_window = {window: scoped[(mode, name, window)] for window in WINDOWS}
            aggregate = merged(list(per_window.values()))
            trace = [row for row in run["progress"] if row.get("mode") == mode and row.get("stage") == name]
            first_green = next((row["elapsedMs"] for row in trace if row.get("event") == "assessed" and
                row.get("passed") == row.get("total")), None)
            fact_names = ["PROJECT-GOAL.md", "SPEC.md", "CHANGE-G2.md"]
            host_owned = ["INDEX.md", "modules/architecture.md", "LEDGER.md"] if mode == "building-loop" else []
            stages.append({
                "run": run["run"], "mode": mode, "stage": name, "terminal": stage["terminal"],
                "phase": stage.get("nativePhase"), "elapsedMs": stage["elapsedMs"], "firstGreenMs": first_green,
                "carry": stage["carry"], "score": stage["score"], "score210": stage["comparison"]["score"],
                "projectDocuments": sorted(set(stage.get("documents", {})) - set(fact_names) - set(host_owned)),
                "architectureRegistered": bool(stage.get("registeredArchitecture")),
                "ledgerItems": len(stage.get("ledgerItems", [])), "extraPython": stage.get("extraPython", []),
                "token210": per_window["comparison"]["totalTokens"], "cache210": cache(per_window["comparison"]),
                "tokenAll": aggregate["totalTokens"], "cacheAll": cache(aggregate), "usage": per_window,
            })
    totals = []
    for mode in MODES:
        per_window = {window: modes[(mode, window)] for window in WINDOWS}
        agg = merged(list(per_window.values()))
        totals.append({"mode": mode, "token210": per_window["comparison"]["totalTokens"],
                       "cache210": cache(per_window["comparison"]), "tokenAll": agg["totalTokens"],
                       "cacheAll": cache(agg), "usage": per_window, "totalUsage": agg})
    return {"totals": totals, "stages": stages, "sourceRunIds": [run["run"] for run in doc["runs"]],
            "scope": "Measured DeepSeek provider usage only; cancellation, missing provider usage, and unsent requests remain unknown.",
            "persistedUnattributed": sum(len(run["persistedUsageOutsideWindow"].get("unknown", [])) for run in doc["runs"]),
            "journalReadErrors": sum(len(run["persistedUsageOutsideWindow"].get("errors", [])) for run in doc["runs"])}

if __name__ == "__main__":
    src = Path(sys.argv[1])
    dest = Path(sys.argv[2])
    metrics = analyze(json.loads(src.read_text(encoding="utf-8")))
    dest.write_text(json.dumps(metrics, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    for row in metrics["totals"]:
        print(row["mode"], "210", row["token210"], row["cache210"], "all", row["tokenAll"], row["cacheAll"])
    for row in metrics["stages"]:
        print(row["run"], row["mode"], row["stage"], row["score"]["allPass"], row["terminal"], row["phase"],
              row["carry"], row["firstGreenMs"], row["token210"], row["tokenAll"])

