"""Sanitize recorded native observations and recompute aggregate usage."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent
FILES = ("journal.py", "planner.py", "policy.py", "release.py")
WINDOWS = re.compile(r"(?i)\b[CG]:[/\\](?:Users|CodexProjects|CodexArchive)(?:[/\\][^\s`'\"<>,;]*)?")
SECRET = re.compile(r"(?i)\b(?:sk|ds|ghp|github_pat)-[A-Za-z0-9_-]{12,}|([?&]token=)[^\s`'\"]+")


ENV_SECRETS = tuple(value for name, value in os.environ.items()
                    if re.search(r"(?i)(?:deepseek|openai|github).*(?:key|token)", name) and len(value) >= 12)


def read(path, default=None):
    if not path.is_file():
        return default
    return json.loads(path.read_text(encoding="utf-8-sig"))


def events(path):
    if not path.is_file():
        return []
    result = []
    for row in path.read_text(encoding="utf-8-sig").splitlines():
        if row.strip():
            try:
                result.append(json.loads(row))
            except json.JSONDecodeError:
                result.append({"type": "incomplete-event-row"})
    return result


def scrub(value):
    if isinstance(value, str):
        for secret in ENV_SECRETS:
            value = value.replace(secret, "[redacted]")
        return SECRET.sub("[redacted]", WINDOWS.sub("[local-path]", value))
    if isinstance(value, dict):
        return {key: scrub(item) for key, item in value.items()}
    if isinstance(value, list):
        return [scrub(item) for item in value]
    return value


def usage(rows, window=None):
    grouped = defaultdict(lambda: {"responses": 0, "withUsage": 0, "inputTokens": 0,
                                  "outputTokens": 0, "cacheReadTokens": 0, "cacheWriteTokens": 0,
                                  "totalTokens": 0, "mismatch": 0})
    for row in rows:
        if row.get("type") != "assistant/message" or (window is not None and row.get("window") != window):
            continue
        u = row.get("usage")
        bucket = grouped[(row["mode"], row["stage"], row["role"])]
        bucket["responses"] += 1
        if not u:
            continue
        bucket["withUsage"] += 1
        names = ("inputTokens", "outputTokens", "cacheReadTokens", "cacheWriteTokens")
        for key in (*names, "totalTokens"):
            bucket[key] += u.get(key) or 0
        if sum(u.get(key) or 0 for key in names) != u["totalTokens"]:
            bucket["mismatch"] += 1
    return [{"mode": mode, "stage": stage, "role": role, **value}
            for (mode, stage, role), value in sorted(grouped.items())]


def artifact(path):
    blob = path.read_bytes()
    raw = blob.decode("utf-8", "replace")
    text = scrub(raw)
    item = {"sha256": hashlib.sha256(blob).hexdigest(), "text": text}
    if text != raw:
        item["publishedTextSha256"] = hashlib.sha256(text.encode("utf-8")).hexdigest()
    return item


def receipts(root):
    def identity_fields(value):
        if isinstance(value, dict):
            return {key: hashlib.sha256(item.encode()).hexdigest()[:12]
                    if key in {"actor", "auditor", "reviewer"} and isinstance(item, str)
                    else identity_fields(item) for key, item in value.items()}
        if isinstance(value, list):
            return [identity_fields(item) for item in value]
        return value

    rows = []
    for lane in ("bl", "bl2"):
        for path in sorted((root / "work" / lane / "receipts").glob("*.json")):
            data = read(path, {})
            role = data.get("reviewer") or data.get("auditor")
            payload = {key: data[key] for key in ("unit", "phase", "goal", "candidateSha256", "decision",
                       "codeRegression", "codeReview", "independentAudit") if key in data}
            rows.append({"lane": lane, "name": path.name,
                         "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                         "roleIdentity": hashlib.sha256(role.encode()).hexdigest()[:12] if isinstance(role, str) else None,
                         "receipt": identity_fields(payload)})
    return rows


def scoring(baseline, final):
    before = {case["id"] for case in baseline["cases"] if case["status"] == "passed"}
    after = {case["id"] for case in final["cases"] if case["status"] == "passed"}
    all_previous = {case["id"] for case in baseline["cases"]}
    all_current = {case["id"] for case in final["cases"]}
    new = all_current - all_previous
    return {"retained": len(before & after), "protected": len(before), "newPass": len(new & after), "newTotal": len(new),
            "allPass": len(after), "allTotal": len(all_current),
            "architectureEdges": sum(bool(value.get("boundaryOk")) for value in final["architecture"].values()),
            "architectureIO": sum(bool(value.get("transportOnlyIO")) for value in final["architecture"].values())}


def run(root):
    meta = read(root / "metadata.json", {})
    result = read(root / "result.json", {})
    calls = events(root / "events.jsonl")
    witness = root / "h" / "profiles" / "qa" / "witness.mjs"
    meta["loadedWitnessSha256"] = hashlib.sha256(witness.read_bytes()).hexdigest() if witness.is_file() else None
    completed = []
    for mode in ("standard", "standard-checklist", "building-loop"):
        for stage in ("g1", "g2"):
            item = read(root / (mode + "-" + stage + ".json"))
            if not item:
                continue
            frozen = root / "frozen" / mode / stage
            item["frozenSource"] = {name: artifact(frozen / name) for name in FILES if (frozen / name).is_file()}
            item["frozenHandoff"] = artifact(frozen / "HANDOFF.md") if (frozen / "HANDOFF.md").is_file() else None
            item["score"] = scoring(item["baseline"], item["final"])
            comparison = item.get("comparison")
            if comparison:
                checkpoint = root / "checkpoint" / mode / stage
                comparison["score"] = scoring(item["baseline"], comparison["assessment"])
                if checkpoint.is_dir():
                    comparison["source"] = {name: artifact(checkpoint / name) for name in FILES if (checkpoint / name).is_file()}
            completed.append(item)
    post_host_architecture = []
    for lane in ("bl", "bl2"):
        path = root / "work" / lane / "modules" / "architecture.md"
        if path.is_file():
            post_host_architecture.append({"lane": lane, "snapshot": artifact(path)})
    return scrub({"run": root.name, "metadata": meta, "outcome": {"error": result.get("error"),
        "preflight": result.get("preflight"), "laneErrors": [row["error"] for row in result.get("lanes", []) if "error" in row]},
        "superseded": read(root / "superseded.json"), "stages": completed, "progress": events(root / "progress.jsonl"),
        "events": calls, "roleUsage": usage(calls), "roleUsageByWindow": {window: usage(calls, window)
            for window in ("comparison", "extension", "cleanup")}, "persistedReceipts": receipts(root),
        "postHostArchitecture": post_host_architecture,
        "persistedUsageOutsideWindow": read(root / "persisted-usage-outside-window.json", {})})


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("destination", type=Path)
    parser.add_argument("runs", nargs="*", type=Path)
    args = parser.parse_args()
    roots = args.runs or sorted(ROOT.glob("r-*"))
    roots = [path.resolve(strict=True) for path in roots]
    destination = args.destination.resolve()
    if not destination.is_relative_to(ROOT) or any(not path.is_relative_to(ROOT) for path in roots):
        raise SystemExit("Use the isolated G drive engineering QA folder.")
    fixture_names = ["SPEC.md", "CHANGE-G2.md", "METHOD.md", "assess.py", "base_assess.py", "hard_assess.py", "SPEC-G3.md", "CHANGE-G4.md", "fixture.mjs", "run.mjs", "witness.mjs",
                     "late-usage.mjs", "publish.py", "summary.py", "import-probe.py",
                     "review-probe.py", "probe.py", "python_syntax.py", "measure.py", "oracle-smoke.json"]
    output = {"spec": "building-loop-engineering-three-arm-evidence/1",
              "fixtures": {name: artifact(ROOT / name) for name in fixture_names},
              "seed": {name: artifact(ROOT / "seed" / name) for name in FILES},
              "runs": [run(path) for path in roots]}
    loaded_witnesses = {hashlib.sha256(path.read_bytes()).hexdigest(): artifact(path)
                        for root in roots if (path := root / "h" / "profiles" / "qa" / "witness.mjs").is_file()}
    output["fixtures"]["loadedWitnesses"] = loaded_witnesses
    supplemental = {"f3435": ["f3435-rep3-no-defect-rejection.json", "handoff-pager-raw-compact.json",
                                "f3435-import-probe.json", "f3435-quality-probes.json"],
                    "b795": ["b795-rep1-false-review.json", "b795-rep1-repeated-false-review.json",
                              "b795-import-probe.json", "b795-quality-probes.json"],
                    "cdf0": ["cdf0-example-audit.json", "cdf0-quality-probes.json"],
                    "d8df": ["d8df-example-audit.json", "d8df-quality-probes.json"]}
    shas = [entry["metadata"].get("archiveSha256", "") for entry in output["runs"]]
    attachments = [name for tag, names in supplemental.items() if any(sha.startswith(tag) for sha in shas) for name in names]
    if attachments:
        output["supplementalEvidence"] = {name: artifact(ROOT / name) for name in attachments if (ROOT / name).is_file()}
    for cleanup_path in ROOT.glob("*-process-cleanup.json"):
        cleanup = read(cleanup_path, {})
        if {path.name for path in roots} == set(cleanup.get("runIds", [])):
            output["processCleanup"] = cleanup
            break
    destination.write_text(json.dumps(scrub(output), ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")

