"""Compare the note's generated import section with independent Python AST."""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

from assess import architecture


ROOT = Path(__file__).resolve().parent
HEADING = re.compile(r"^## 静态导入\s*$(.*?)(?=^#{1,2} |\Z)", re.M | re.S)
ROW = re.compile(r'^("(?:[^"\\]|\\.)+") -> (.+)$')


def check(source):
    scan = architecture(source)
    expected = {name + ".py": sorted(dep + ".py" for dep in row["moduleImports"])
                for name, row in scan.items() if row.get("parse")}
    note = (source / "modules" / "architecture.md").read_text(encoding="utf-8")
    sections = HEADING.findall(note)
    if len(sections) != 1:
        return {"status": "missing" if not sections else "repeated", "expected": expected}
    body = sections[0].strip().splitlines()
    if not body or not body[0].startswith("```text") or body[-1] != "```":
        return {"status": "unstructured", "expected": expected}
    actual = {}
    for line in body[1:-1]:
        row = ROW.fullmatch(line)
        if not row:
            return {"status": "invalid-row", "expected": expected}
        path, imports = json.loads(row[1]), json.loads("[" + row[2] + "]") if row[2] != "[]" else []
        if path in actual:
            return {"status": "duplicate-row", "expected": expected}
        actual[path] = imports
    valid = len(expected) == len(scan) and actual == expected
    return {"status": "exact" if valid else "mismatch", "expected": expected, "observed": actual}


if __name__ == "__main__":
    observations = []
    for name in sys.argv[1:]:
        run = (ROOT / name).resolve(strict=True)
        if not run.is_relative_to(ROOT):
            raise SystemExit("Use only the isolated G QA root")
        for mode in ("standard", "building-loop"):
            for stage in ("g1", "g2"):
                for window in ("checkpoint", "frozen"):
                    source = run / window / mode / stage
                    if source.is_dir():
                        observations.append({"run": name, "mode": mode, "stage": stage, "window": window, **check(source)})
    print(json.dumps({"method": "Static direct import rows match independent Python AST; prose, dynamic imports and runtime behavior are assessed separately.",
        "observations": observations}, indent=2))

